// Kollab re-vet diff — compare this run's shortlist against the snapshot from the
// previous run (kept in workflow static data) and emit ONE ITEM PER ALERT.
//
// Alert conditions:
//   (a) risk level worsened            clear -> medium/high, medium -> high
//   (b) engagement rate dropped >40%   vs the snapshotted value
//   (c) new fraud signal               a risk.signals label not present last run
//
// NOTE: workflow static data persists only across PRODUCTION executions
// (the cron, or the webhook's Production URL on an active workflow).
// Editor test runs always start from an empty snapshot.

const staticData = $getWorkflowStaticData('global');
const previous = staticData.kolSnapshot || {};
const isFirstRun = Object.keys(previous).length === 0;

const response = $input.first().json;
const kols = response.kols || [];

const RISK_RANK = { clear: 0, medium: 1, high: 2 };
const ER_DROP_THRESHOLD = 0.4; // fraction — alert when ER fell by more than 40%

const alerts = [];

for (const kol of kols) {
  const prev = previous[kol.id];
  if (!prev) continue; // new to the shortlist: baseline silently, diff from next run

  const signals = (kol.risk && kol.risk.signals) || [];

  // (a) risk level worsened
  if (RISK_RANK[kol.risk.level] > RISK_RANK[prev.riskLevel]) {
    const lead = signals[0]; // vet.py orders badges structural-first, most-severe-first
    alerts.push({
      handle: kol.handle,
      kolId: kol.id,
      change: 'risk_worsened',
      summary:
        'risk ' + prev.riskLevel + ' → ' + kol.risk.level +
        (lead ? ' (' + lead.label + ': ' + lead.detail + ')' : ''),
    });
  }

  // (b) engagement rate dropped more than 40%
  if (prev.engagementRate > 0) {
    const drop = (prev.engagementRate - kol.engagementRate) / prev.engagementRate;
    if (drop > ER_DROP_THRESHOLD) {
      alerts.push({
        handle: kol.handle,
        kolId: kol.id,
        change: 'engagement_drop',
        summary:
          'engagement ' + prev.engagementRate + '% → ' + kol.engagementRate +
          '% (−' + Math.round(drop * 100) + '% vs last run)',
      });
    }
  }

  // (c) fraud signals that were not present last run
  const prevLabels = new Set(prev.signalLabels || []);
  for (const s of signals) {
    if (!prevLabels.has(s.label)) {
      alerts.push({
        handle: kol.handle,
        kolId: kol.id,
        change: 'new_signal',
        summary: 'new fraud signal — ' + s.label + ': ' + s.detail,
      });
    }
  }
}

// Update the snapshot AFTER diffing, so the next run compares against this one.
const nextSnapshot = {};
for (const kol of kols) {
  nextSnapshot[kol.id] = {
    handle: kol.handle,
    riskLevel: kol.risk.level,
    engagementRate: kol.engagementRate,
    fitScore: kol.fitScore,
    signalLabels: ((kol.risk && kol.risk.signals) || []).map((s) => s.label),
  };
}
staticData.kolSnapshot = nextSnapshot;
staticData.lastRunAt = new Date().toISOString();

if (alerts.length === 0) {
  return [{ json: { hasAlerts: false, checked: kols.length, firstRun: isFirstRun } }];
}

return alerts.map((a) => ({
  json: { hasAlerts: true, checked: kols.length, runAt: staticData.lastRunAt, ...a },
}));
